// Loads the shared WebAuthn fixtures (generated by
// contracts/generate-fixtures.mjs) for the contract tests.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../../contracts/fixtures',
);

export interface ContractParams {
  rpId: string;
  origin: string;
  challenge: string;
  userId: string;
  credentialId: string;
  cosePublicKey: string;
}

export const params = JSON.parse(
  readFileSync(path.join(dir, 'params.json'), 'utf8'),
) as ContractParams;

export const attestation = JSON.parse(
  readFileSync(path.join(dir, 'attestation.json'), 'utf8'),
);

export const assertion = JSON.parse(
  readFileSync(path.join(dir, 'assertion.json'), 'utf8'),
);
